-- V11: Replace the placeholder DISC interpretation scheme with the real
-- 40-pattern classical DISC algorithm ported from
-- "Psikogram DISC_simulasidewi.xlsx" (Psikogram / Sheet3 / Def tabs).
--
-- The old disc_scoring_most/least/dif tables modeled scoring as ONE combined
-- 4-key lookup (d_score,i_score,s_score,c_score) -> single code, which never
-- matched the source spreadsheet and always fell through to a generic
-- "Profil Beragam" fallback. The real algorithm instead:
--   1. Converts each of the 4 raw D/I/S/C tallies independently through a
--      per-line lookup table (disc_most_conversion / disc_least_conversion /
--      disc_dif_conversion below, transcribed from the "Sheet3" tab).
--   2. Classifies the resulting 4 converted values against 40 ordered
--      mutually-exclusive boolean rules (ported in DiscPatternClassifier.java)
--      to get a pattern index 1-40.
--   3. Looks up that index in disc_pattern_profiles (transcribed from the
--      "Def" tab) for the title, trait list, description and job
--      recommendations.
-- This runs three times per result — once each for the MOST, LEAST and DIF
-- lines — matching the Psikogram report's "Kepribadian Saat di Publik",
-- "Kepribadian Saat Mendapat Tekanan" and "Kepribadian Asli / Sesungguhnya"
-- sections.

DROP TABLE IF EXISTS disc_scoring_most;
DROP TABLE IF EXISTS disc_scoring_least;
DROP TABLE IF EXISTS disc_scoring_dif;
DROP TABLE IF EXISTS disc_personality_profiles;

CREATE TABLE disc_most_conversion (
    raw_value INT PRIMARY KEY,   -- 0-20 (clamped beyond range)
    d_conv    NUMERIC(4,2) NOT NULL,
    i_conv    NUMERIC(4,2) NOT NULL,
    s_conv    NUMERIC(4,2) NOT NULL,
    c_conv    NUMERIC(4,2) NOT NULL
);

CREATE TABLE disc_least_conversion (
    raw_value INT PRIMARY KEY,   -- 0-20 (clamped beyond range)
    d_conv    NUMERIC(4,2) NOT NULL,
    i_conv    NUMERIC(4,2) NOT NULL,
    s_conv    NUMERIC(4,2) NOT NULL,
    c_conv    NUMERIC(4,2) NOT NULL
);

CREATE TABLE disc_dif_conversion (
    raw_value INT PRIMARY KEY,   -- -22 to 22 (clamped beyond range)
    d_conv    NUMERIC(4,2) NOT NULL,
    i_conv    NUMERIC(4,2) NOT NULL,
    s_conv    NUMERIC(4,2) NOT NULL,
    c_conv    NUMERIC(4,2) NOT NULL
);

-- pattern_index (1-40) is what DiscPatternClassifier resolves to; type_key is
-- the classic DISC notation (e.g. "D / I-D") kept for reference/admin display.
CREATE TABLE disc_pattern_profiles (
    id                  BIGSERIAL PRIMARY KEY,
    pattern_index       INT UNIQUE NOT NULL,
    type_key            VARCHAR(30) NOT NULL,
    title               VARCHAR(100) NOT NULL,
    traits              JSONB NOT NULL,        -- ordered array of trait phrases
    description         TEXT NOT NULL,
    job_recommendations TEXT NOT NULL
);

-- disc_results: add the 3 lookups the report needs. profile_title/profile_desc
-- (already in the table since V2) are repurposed to hold the DIF/"real
-- personality" profile — the headline result — so only MOST/LEAST plus DIF's
-- traits and job recommendations need new columns.
ALTER TABLE disc_results
    ADD COLUMN most_profile_title   VARCHAR(100),
    ADD COLUMN most_profile_traits  JSONB,
    ADD COLUMN least_profile_title  VARCHAR(100),
    ADD COLUMN least_profile_traits JSONB,
    ADD COLUMN dif_profile_traits   JSONB,
    ADD COLUMN job_recommendations  TEXT;

-- most_key/least_key/dif_key held the old scheme's short codes (VARCHAR(10),
-- e.g. "DI"); real type_keys like "D / S-D-C / S-C-D" run longer.
ALTER TABLE disc_results
    ALTER COLUMN most_key TYPE VARCHAR(30),
    ALTER COLUMN least_key TYPE VARCHAR(30),
    ALTER COLUMN dif_key TYPE VARCHAR(30);

-- Existing rows were produced by the old placeholder logic (mostly the
-- generic "Profil Beragam" fallback) — dev-only data, safe to clear so every
-- remaining result reflects the real algorithm.
TRUNCATE TABLE disc_results RESTART IDENTITY;



